/* Flat laydown photographs of the Jerzees 975MPR joggers, one per colour, with the print
   rectangle measured on them.

   Printful publishes no flat TEMPLATE for this blank -- its mockup-generator templates are
   all worn model photos -- but its mockup GENERATOR will render the flat front view. Each
   image here is that render with a fully transparent print file, i.e. the garment blank,
   produced once through /api/blank. The rectangles come from the same render done with a
   magenta calibration sheet filling the print area, read back pixel by pixel.

   Coordinates are in the 1000 x 1000 space of these images: [left, top, width, height].
   leg_left is the WEARER's left, which is the right-hand leg of this front view.

   Loaded on demand by app.js the first time the joggers are opened, so 150 kB does not sit
   in front of anyone who never clicks SWEATPANTS. */
window.TM_PANTS = {
  size: 1000,
  rect: { leg_left: [715, 366, 89, 344], leg_right: [197, 367, 88, 343] },
  img: {
    'black': 'data:image/webp;base64,',
    'athletic-heather': 'data:image/webp;base64,',
    'black-heather': 'data:image/webp;base64,',
    'j-navy': 'data:image/webp;base64,'
  }
};
